if ((wheels == NULL) || (momentum == NULL) || (momentum_norm == NULL) || 
    (energy == NULL) || (fastest == NULL)) {
    return ADCS_E_NULL;
}

if (count != 4) {
    return ADCS_E_RANGE;
}

*momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
*momentum_norm = 0.0;
*energy = 0.0;
*fastest = SIZE_MAX;

adcs_vec3_t normalized_axis;
double current_energy = 0.0;
double max_abs_speed = -1.0;
size_t fastest_idx = SIZE_MAX;

for (size_t i = 0; i < 4; i++) {
    const adcs_wheel_t *w = &wheels[i];

    if ((!isfinite(w->inertia_kg_m2)) || (w->inertia_kg_m2 <= 0.0)) {
        return ADCS_E_RANGE;
    }

    if (!isfinite(w->speed_rad_s)) {
        return ADCS_E_RANGE;
    }

    if (adcs_vec3_normalize(&w->axis_body, ADCS_EPS_NORM, &normalized_axis) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    double scalar = w->inertia_kg_m2 * w->speed_rad_s;
    adcs_vec3_t wheel_h = adcs_vec3_scale(&normalized_axis, scalar);
    *momentum = adcs_vec3_add(momentum, &wheel_h);

    current_energy += 0.5 * w->inertia_kg_m2 * w->speed_rad_s * w->speed_rad_s;

    double abs_speed = fabs(w->speed_rad_s);
    if (i == 0) {
        max_abs_speed = abs_speed;
        fastest_idx = 0;
    } else {
        if (abs_speed > max_abs_speed) {
            max_abs_speed = abs_speed;
            fastest_idx = i;
        }
    }
}

*energy = current_energy;
*momentum_norm = adcs_vec3_norm(momentum);
*fastest = fastest_idx;

return ADCS_OK;

